// Flow Arena records — the derivations behind GET /api/arena/results
// and the fighter passports (offchain/mint-passport.js).
//
// SINGLE SOURCE OF TRUTH: every figure here folds api/_records-
// data.json, the frozen record set generated by offchain/generate-
// records-data.js from the repo's own records (offchain/arena-
// standings-history.json, offchain/arena-live-report.json,
// offchain/floor/exhibition/*.standings-record.json). The results
// feed and the passports fold the SAME rows through THIS module, so
// they can never disagree.
//
// Counted and exhibition records are kept in separate lists in the
// data file and in separate sections here — never blended. Counted =
// OFFICIAL-class matches (career standings). Exhibitions are the
// floor's exhibition-class events.

const data = require("./_records-data.json");

const round2 = (n) => Math.round(Number(n || 0) * 100) / 100;

/** Prize per cent of data spent — the house efficiency metric. */
function prizePerCent(prizesUsd, dataUsd) {
  if (!(dataUsd > 0)) return prizesUsd > 0 ? null : 0;
  return round2(prizesUsd / (dataUsd * 100));
}

function seatEfficiency(seat) {
  return prizePerCent(seat.payout, seat.dataSpend);
}

/** One per-seat row for the results feed. */
function resultRow(match, seat) {
  return {
    matchId: match.matchId,
    fighter: seat.name,
    fighterId: seat.fighterId,
    placing: seat.rank,
    prizeUsd: round2(seat.payout),
    dataUsd: round2(seat.dataSpend),
    efficiency: seatEfficiency(seat),
    trades: seat.trades,
    pnlUsd: round2(seat.pnl),
  };
}

/** All counted per-seat rows, in match order — the SKR feed shape. */
function countedRows() {
  const rows = [];
  for (const m of data.countedMatches) {
    for (const seat of [...m.seats].sort((a, b) => a.rank - b.rank)) {
      rows.push(resultRow(m, seat));
    }
  }
  return rows;
}

function aggregate(events, fighterId) {
  const mine = [];
  for (const ev of events) {
    const seat = ev.seats.find((s) => s.fighterId === fighterId);
    if (seat) mine.push({ matchId: ev.matchId, klass: ev.klass, source: ev.source, seat });
  }
  if (!mine.length) return null;
  const prizes = round2(mine.reduce((s, x) => s + x.seat.payout, 0));
  const dataSpend = round2(mine.reduce((s, x) => s + x.seat.dataSpend, 0));
  return {
    matches: mine.length,
    wins: mine.filter((x) => x.seat.rank === 1).length,
    prizesUsd: prizes,
    dataUsd: dataSpend,
    efficiency: prizePerCent(prizes, dataSpend),
    trades: mine.reduce((s, x) => s + (x.seat.trades || 0), 0),
    pnlUsd: round2(mine.reduce((s, x) => s + (x.seat.pnl || 0), 0)),
    perMatch: mine.map((x) => ({
      matchId: x.matchId,
      placing: x.seat.rank,
      prizeUsd: round2(x.seat.payout),
      dataUsd: round2(x.seat.dataSpend),
      efficiency: seatEfficiency(x.seat),
      trades: x.seat.trades || 0,
      pnlUsd: round2(x.seat.pnl || 0),
    })),
    receipts: mine.map((x) => ({ matchId: x.matchId, source: x.source })),
  };
}

/** The counted (career) record for one fighter, or null. */
function countedRecord(fighterId) {
  return aggregate(data.countedMatches, fighterId);
}

/** The exhibition record for one fighter (optionally scoped to a
 *  matchId prefix — FLOWX's passport is scoped to his formula-v1
 *  series), or null. */
function exhibitionRecord(fighterId, matchIdPrefix) {
  const events = matchIdPrefix
    ? data.exhibitionEvents.filter((e) => e.matchId.startsWith(matchIdPrefix))
    : data.exhibitionEvents;
  return aggregate(events, fighterId);
}

function fighterIds() {
  const ids = new Set();
  for (const m of [...data.countedMatches, ...data.exhibitionEvents]) {
    for (const s of m.seats) ids.add(s.fighterId);
  }
  return [...ids].sort();
}

function resultsBody() {
  return {
    service: "flow-arena-results",
    class: "counted",
    note:
      "Per-seat results for COUNTED (OFFICIAL-class) Flow Arena matches only. Exhibitions are excluded from this feed and from every figure in it: exhibition-class records live in each fighter's passport (GET /api/passport?id=<fighterId>, exhibition section) and in the repo's raw standings records (offchain/floor/exhibition/*.standings-record.json). Figures fold the same frozen record set the passports are minted from (api/_records.js over api/_records-data.json), so the two can never disagree.",
    generatedAt: data.generatedAt,
    matches: data.countedMatches.map((m) => m.matchId),
    rows: countedRows(),
  };
}

module.exports = {
  data,
  round2,
  prizePerCent,
  countedRows,
  countedRecord,
  exhibitionRecord,
  fighterIds,
  resultsBody,
};
